import { useEffect, useState } from "react";

export default function UserList({ enabled }) {
  const [users, setUsers] = useState([]);

  if (enabled) {
    useEffect(() => {
      fetch("/api/users").then((r) => r.json()).then(setUsers);
    }, []);
  }

  return <ul>{users.map((u) => <li key={u.id}>{u.name}</li>)}</ul>;
}
